#!/usr/bin/env python3
"""
Run this once to install standalone wyckoff_alert.py:
  python patch_alert.py
Then:
  python wyckoff_alert.py
"""
import os, base64, zlib

DATA = ""

target = os.path.join(os.path.dirname(os.path.abspath(__file__)), "wyckoff_alert.py")
content = zlib.decompress(base64.b64decode(DATA))
with open(target, "wb") as f:
    f.write(content)
print("[OK] wyckoff_alert.py installed ->", target)
print("[OK] Standalone -- no bitunix_scanner/ needed")
print("[OK] Weekly / Daily / 4H Wyckoff spring scan + live monitor")
print("")
print("Now run:  python wyckoff_alert.py")
